# Write your MySQL query statement below
select  CONCAT(Year(trans_date) , '-' , CASE WHEN MONTH(trans_date ) < 10 then CONCAT('0','',MONTH(trans_date ) ) ELSE   MONTH(trans_date )  END ) as month , country , count(CASE WHEN state='approved' then 1 else 0 end ) as trans_count  , sum(case when state = 'approved' then 1 else 0 end) as approved_count  ,SUM(amount) as trans_total_amount  , sum(case when state = 'approved' then amount else 0 end) as approved_total_amount  from Transactions group by month , country ;